text.2809:
/*

This program doesn't detect edges with compass operators and a laplacian
operator. It should output 2 raw grey-scale images with edges. The output
doesn't look like edges at all.

In novicee terms, how do I correct the errors? Any improvements are welcome.
(I'll even accept your corrected code.)

(If I convolve the INPUT.IMAGE with a digital gaussian [7 by 7] to remove
noise, will I get an improvement with the laplacian.)

--------------------------2 types of edge detection-------------------------*/
#include <stdio.h> 
#include <math.h> 

#define IMAGEWIDTH 300
#define IMAGEHEIGHT 300

unsigned char Input_Image [IMAGEHEIGHT][IMAGEWIDTH];

unsigned char Angles_Wanted [IMAGEHEIGHT][IMAGEWIDTH];
unsigned char Magnitude_Image [IMAGEHEIGHT][IMAGEWIDTH];

int Laplace_Op1 [3][3] = { 0,-1, 0, -1,4,-1,  0,-1, 0};

int Compass_Op1 [3][3] = { 1, 1, 1,  0,0, 0, -1,-1,-1};
int Compass_Op2 [3][3] = { 1, 1, 0,  1,0,-1,  0,-1,-1};
int Compass_Op3 [3][3] = { 1, 0,-1,  1,0,-1,  1, 0,-1};
int Compass_Op4 [3][3] = { 0,-1,-1,  1,0,-1,  1, 1, 0};
int Compass_Op5 [3][3] = {-1,-1,-1,  0,0, 0,  1, 1, 1};
int Compass_Op6 [3][3] = {-1,-1, 0, -1,0, 1,  0, 1, 1};
int Compass_Op7 [3][3] = {-1, 0, 1, -1,0, 1, -1, 0, 1};
int Compass_Op8 [3][3] = { 0, 1, 1, -1,0, 1, -1,-1, 0};

void Compass (row,col)
int row,col;
{
  int value;
  int op_rows, op_cols;
  int Compass1,Compass2,Compass3,Compass4;
  int Compass5,Compass6,Compass7,Compass8;

  Compass1 = Compass2 = Compass3 = Compass4 = 0;
  Compass5 = Compass6 = Compass7 = Compass8 = 0;

  for (op_rows = -1; op_rows < 2; op_rows++)
    for (op_cols = -1; op_cols < 2; op_cols++)
      {
	if (((row + op_rows) >= 0) && ((col + op_cols) >= 0))
	  {

	    Compass1 += ((int) Input_Image [row + op_rows][col + op_cols]) * 
	                       Compass_Op1 [op_rows + 1][op_cols + 1];
	    Compass2 += ((int) Input_Image [row + op_rows][col + op_cols]) * 
	                       Compass_Op2 [op_rows + 1][op_cols + 1];
	    Compass3 += ((int) Input_Image [row + op_rows][col + op_cols]) * 
	                       Compass_Op3 [op_rows + 1][op_cols + 1];
	    Compass4 += ((int) Input_Image [row + op_rows][col + op_cols]) * 
	                       Compass_Op4 [op_rows + 1][op_cols + 1];
	    Compass5 += ((int) Input_Image [row + op_rows][col + op_cols]) * 
	                       Compass_Op5 [op_rows + 1][op_cols + 1];
	    Compass6 += ((int) Input_Image [row + op_rows][col + op_cols]) * 
	                       Compass_Op6 [op_rows + 1][op_cols + 1];
	    Compass7 += ((int) Input_Image [row + op_rows][col + op_cols]) * 
	                       Compass_Op7 [op_rows + 1][op_cols + 1];
	    Compass8 += ((int) Input_Image [row + op_rows][col + op_cols]) * 
	                       Compass_Op8 [op_rows + 1][op_cols + 1];

	  }
      }
  if (Compass1 < Compass2)
    value = Compass2;
  else 
    value = Compass1;      
  if (value < Compass3)
    value = Compass3;
  if (value < Compass4)
    value = Compass4;
  if (value < Compass5)
    value = Compass5;
  if (value < Compass6)
    value = Compass6;
  if (value < Compass7)
    value = Compass7;
  if (value < Compass8)
    value = Compass8;

  Magnitude_Image [row][col] = (char) value;
}

void Laplace1 (row,col)
int row,col;
{
  int op_rows, op_cols;

  Magnitude_Image [row][col] = 0;
  for (op_rows = -1; op_rows < 2; op_rows++)
    for (op_cols = -1; op_cols < 2; op_cols++)
      if (((row + op_rows) >= 0) && ((col + op_cols) >= 0))
	Magnitude_Image [row][col] = 
	  (char) ((int)Magnitude_Image [row][col] +
		  ((int) Input_Image [row + op_rows][col + op_cols] * 
		   Laplace_Op1 [op_rows + 1][op_cols + 1]));
}

main  ()
{
  FILE *Original_Image_fp;
  FILE *Laplace1_mag_fp,*Laplace2_mag_fp,*Laplace3_mag_fp;
  FILE *Compass_mag_fp;

  int row, col, Algo_Count;

  Original_Image_fp = fopen ("INPUT.IMAGE","rb");

  Laplace1_mag_fp = fopen ("Laplace1_Magnitude","wb");
  Compass_mag_fp = fopen ("Compass_Magnitude","wb");

  fread ((unsigned char *) Input_Image,sizeof(unsigned char),IMAGEHEIGHT * IMAGEWIDTH,Original_Image_fp);
  for (Algo_Count = 0; Algo_Count < 2;Algo_Count ++)
    {
      for (row = 0; row < IMAGEHEIGHT; row++) 
	for (col = 0; col < IMAGEWIDTH; col++) 
	  if (!Algo_Count)
	    Laplace1 (row,col);
	  else 
	    Compass (row,col);

      if (!Algo_Count)
	fwrite(Magnitude_Image,sizeof(char),IMAGEHEIGHT * IMAGEWIDTH,Laplace1_mag_fp);
      else 
	fwrite(Magnitude_Image,sizeof(char),IMAGEHEIGHT * IMAGEWIDTH,Compass_mag_fp);
    }
}

text.2958:
} I would like more info on this if anybody has it. Our Exabyte
} 8500 tapedrive has never been working from the Quadra 950.
} We have been trying it since September 1992, replaced cabling,
} inits, I don't know what all. All the "industry experts" we
} phoned (the tapedrive dealer, our Apple dealer, the software
} dealer) all say it's our fault, or they don't know. The last
} thing they said was that we needed a special Quadra SCSI terminator
} (???). Anybody know more? Thanks,


I have been using the PLI (SONY) 3.5" MO drive and now a Sharp color
scanner using standard SCSI cables and STANDARD $20 terminator on my Q700. 
No problems.  If you were using a IIfx, that might be another story.

Make sure there is only one terminator in the cabling and it must be at the
end.  Some boxes have internal terminators; some can be switched out and
others are socketted.  These count.  If the box with internal terminations
cannot be put on the end to terminate the cabling, they have to be
disabled, ie, switched out or pulled out of their sockets.  If you have 2
boxes with internal terminations, the terminations in one box has to be
disabled...., etc.  I am sure that this has been covered by the "experts".

My experience with SCSI boxes that connect to the Mac indicates that they
must have some software package for the Mac to 'talk' to them.  My PLI MO
drive and Sharp scanner has one for each.

Good luck.

text.3153:
We developed a toolkit running on the X Window System.
The toolkit copes with any languages based on X11R5's i18n
facility. As you know, there are 2 kinds of i18n implementation from MIT's 
X11R5 release -- Xsi and Ximp. Our original implementation of the toolkit
uses Xsi.

Our toolkit manages each character's size based on our own font management system.
In order to do that, the 'wchar_t' typed character strings must be decomposed
to character sets. This means that if one wchar_t type compound string with 
ASCII and Kanji mixed, for example, is given, each element of the wchar_t
array must be checked its corresponding character set based on a bit layout
and application environment's locale. In this case if the locale is 'japanese',
each wchar_t character will be classified either to iso8859-1, jisx0208 or so.

We need a function to do this. The function must check how many characters
from the top are the same character set and what the character set is.

We could not find any public X11R5 function to do that and inevitably, used
Xsi's internal functions to construct that function. The following is the
source code of that function 'decomposeCharacterSet()'.


//I18N.h
// This may look like C code, but it is really -*- C++ -*-
// $Id: I18N.h,v 1.1 1992/01/21 12:05:24 iima Exp iima $

#ifndef _I18N_H
#define _I18N_H

#include <X11/Xlib.h>

extern int decomposeCharacterSet(const wchar_t *wc_str,	/* IN */
				 int wc_len,		/* IN */
				 char *buf,		/* OUT */
				 int *buflen,		/* IN/OUT */
				 int *scanned_len,	/* OUT */
				 char **charset);	/* OUT */
extern XmString wcharToXmString(const wchar_t *wc_str);
extern XmStringCharSet charsetOfWchar(const wchar_t wc);

#endif /* _I18N_H */

//I18N.cc
/* $Id: I18N.cc,v 1.1 1992/01/21 12:05:05 iima Exp $ */

#include <stdlib.h>
#include <X11/Xlibint.h>
#include <Xm/Xm.h>
#include "I18N.h"

extern "C" {
#include <X11/wchar.h>
#define _XwcDecomposeGlyphCharset XXX_XwcDecomposeGlyphCharset
#define _Xmbfscs XXX_Xmbfscs
#define _Xmbctidtocsid XXX_Xmbctidtocsid
#include "Xlocaleint.h"
#undef _XwcDecomposeGlyphCharset
#undef _Xmbfscs
#undef _Xmbctidtocsid
    extern int _XwcDecomposeGlyphCharset(XLocale, const wchar_t*, int,
					 char*, int*, int*, int*);
    extern Charset *_Xmbfscs(XLocale, _CSID);
    extern _CSID _Xmbctidtocsid(XLocale, _CSID);
};

int decomposeCharacterSet(const wchar_t *wc_str,/* IN */
			  int wc_len,		/* IN */
			  char *buf,		/* OUT */
			  int *buf_len,		/* IN/OUT */
			  int *scanned_len,	/* OUT */
			  char **charset)	/* OUT */
{
    XLocale xlocale = _XFallBackConvert();
    int ctid;
    int status;
    Charset *xcharset;

    status = _XwcDecomposeGlyphCharset(xlocale, wc_str, wc_len, buf,
				       buf_len, scanned_len, &ctid);
    if (status == Success) {
	xcharset = _Xmbfscs(xlocale, _Xmbctidtocsid(xlocale, ctid));
	*charset = (xcharset) ? xcharset->cs_name : NULL;
    }
    else
	*charset = NULL;
    return status;
}
----------------

An included file above, "Xlocaleint.h", is also Xsi internal and we copied
the file to the toolkit directory and compiled.

A serious issue occured when we tried to compile a toolkit application on
our HP machine with its OS version of HP-UX9.01.

When we tried to link an application based on our toolkit,
link errors occured saying that the following functions are missing:
    _Xmbctidtocsid (code)
    _Xmbfscs (code)
    _XwcDecomposeGlyphCharset (code)
    _XFallBackConvert (code)

We had used MIT release version of X11R5 and its Xsi implementation until
HP-UP9.0 and ran applications successfully. One of the reasons to use Xsi was that
because HP did not release HP's X11R5 until the OS 9.0 and we had no way to 
know how HP's R5 would be implemented. We had hoped Xsi's popularity and used 
its internal functions. 

The HP's linker complains that there are no Xsi internal functions implemented.
We observe from HP's libX11.a, they used some Ximp implementation but we are
not sure if they used MIT's vanilla Ximp version or their own version of Ximp and
therefore, finding just counter part functions in MIT's Ximp for Xsi does not
seem to lead us a solution.

My question and goal is to know how we can construct a function like
'decomposeCharacterset()' listed above. Is there any function to check
character set of each element of wchar_t type strings depending on locales?
If it is a public function, that is perfect but even if it is not, we
want to use any internal functions in HP's X11R5 as we did for MIT's R5.

In order to render a 'wchar_t' type string, there must be some machinery
to judge character sets and that is how the proper fonts are selected for
the string. We have no way to find out that without any HP's X11R5 source 
files. We want to know how we can use that for our goal. 
Any help or comments would be highly appreciated.

I also appreciate if anyone tell me about Ximp treating around this area
even if it is not HP's implementation.

Thank you.

